+package com.example.contact;
+
+import java.time.Instant;
+
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.binder.ValidationResult;
+import com.vaadin.flow.data.binder.ValueContext;
+import com.vaadin.flow.data.validator.EmailValidator;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.RouterLink;
+import com.vaadin.flow.router.Route;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final int MAX_MESSAGE_LENGTH = 500;
+
+    private final ContactMessageService messageService;
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<ContactMessage> grid = new Grid<>(ContactMessage.class, false);
+
+    public ContactView(ContactMessageService messageService) {
+        this.messageService = messageService;
+
+        add(new H1("Contact"));
+        add(new RouterLink("About", AboutView.class));
+
+        send.addClickListener(event -> trySend());
+        send.addClickShortcut(Key.ENTER);
+
+        name.addValueChangeListener(event -> send.setEnabled(true));
+        email.addValueChangeListener(event -> send.setEnabled(true));
+        phone.addValueChangeListener(event -> send.setEnabled(true));
+        message.addValueChangeListener(event -> send.setEnabled(true));
+
+        add(name, email, phone, message, send);
+
+        grid.addColumn(ContactMessage::name).setHeader("Name");
+        grid.addColumn(ContactMessage::email).setHeader("Email");
+        grid.addColumn(ContactMessage::phone).setHeader("Phone");
+        grid.addColumn(ContactMessage::content).setHeader("Message");
+        add(grid);
+
+        refreshGrid();
+    }
+
+    private void trySend() {
+        if (!validate()) {
+            return;
+        }
+
+        ContactMessage sent = new ContactMessage(name.getValue(), email.getValue(), phone.getValue(),
+                message.getValue(), Instant.now());
+        messageService.add(sent);
+        refreshGrid();
+
+        Notification.show("Message sent");
+
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        send.setEnabled(false);
+    }
+
+    private boolean validate() {
+        boolean valid = true;
+
+        name.setInvalid(false);
+        if (name.isEmpty()) {
+            name.setErrorMessage("Name is required");
+            name.setInvalid(true);
+            valid = false;
+        }
+
+        email.setInvalid(false);
+        String emailValue = email.getValue();
+        boolean hasEmail = !email.isEmpty();
+        boolean hasPhone = !phone.isEmpty();
+        if (hasEmail) {
+            ValidationResult result = new EmailValidator("invalid").apply(emailValue, new ValueContext());
+            if (result.isError()) {
+                email.setErrorMessage("Enter a valid e-mail address");
+                email.setInvalid(true);
+                valid = false;
+            }
+        } else if (!hasPhone) {
+            email.setErrorMessage("Give an e-mail address or a phone number");
+            email.setInvalid(true);
+            valid = false;
+        }
+
+        message.setInvalid(false);
+        String messageValue = message.getValue();
+        if (message.isEmpty()) {
+            message.setErrorMessage("Message is required");
+            message.setInvalid(true);
+            valid = false;
+        } else if (messageValue.length() > MAX_MESSAGE_LENGTH) {
+            message.setErrorMessage("Message must be at most " + MAX_MESSAGE_LENGTH + " characters");
+            message.setInvalid(true);
+            valid = false;
+        }
+
+        return valid;
+    }
+
+    private void refreshGrid() {
+        grid.setItems(messageService.list());
+    }
+
+    private boolean hasUnsavedInput() {
+        return !name.isEmpty() || !email.isEmpty() || !phone.isEmpty() || !message.isEmpty();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasUnsavedInput()) {
+            return;
+        }
+
+        BeforeLeaveEvent.ContinueNavigationAction action = event.postpone();
+
+        Dialog dialog = new Dialog();
+        dialog.setHeaderTitle("Discard unsaved message?");
+        dialog.add("You have entered a message that has not been sent yet.");
+
+        Button keepEditing = new Button("Keep editing", event2 -> dialog.close());
+        Button discard = new Button("Discard", event2 -> {
+            dialog.close();
+            action.proceed();
+        });
+        dialog.getFooter().add(keepEditing, discard);
+
+        dialog.open();
+    }
+}
