+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+public class ContactViewBrowserTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @BeforeAll
+    static void setupPlaywright() {
+        AbstractBasePlaywrightIT.setup();
+    }
+
+    @AfterAll
+    static void cleanupPlaywright() {
+        AbstractBasePlaywrightIT.cleanup();
+    }
+
+    @BeforeEach
+    void openPage() throws Exception {
+        setupTest();
+    }
+
+    @AfterEach
+    void closePage() {
+        cleanupTest();
+    }
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port + "/";
+    }
+
+    @Override
+    public String getView() {
+        return "contact";
+    }
+
+    @Test
+    void sendingAMessageShowsItInTheGrid() {
+        TextFieldElement name = TextFieldElement.getByLabel(page, "Name");
+        EmailFieldElement email = EmailFieldElement.getByLabel(page, "Email");
+        TextAreaElement message = TextAreaElement.getByLabel(page, "Message");
+        ButtonElement send = ButtonElement.getByText(page, "Send");
+
+        int before = GridElement.get(page).getRenderedRowCount();
+
+        name.setValue("Browser Person");
+        email.setValue("browser@example.com");
+        message.setValue("Hello from the browser test");
+        send.click();
+
+        NotificationElement notification = NotificationElement.getByText(page, "Message sent");
+        notification.assertOpen();
+
+        assertEquals("", name.getValue());
+        assertEquals("", email.getValue());
+        assertEquals("", message.getValue());
+        assertFalse(send.isEnabled());
+
+        GridElement grid = GridElement.get(page);
+        grid.assertRowCount(before + 1);
+        grid.assertCellContent(0, "Name", "Browser Person");
+    }
+
+    @Test
+    void emptyFormShowsValidationErrors() {
+        ButtonElement send = ButtonElement.getByText(page, "Send");
+        send.click();
+
+        TextFieldElement name = TextFieldElement.getByLabel(page, "Name");
+        EmailFieldElement email = EmailFieldElement.getByLabel(page, "Email");
+        TextAreaElement message = TextAreaElement.getByLabel(page, "Message");
+
+        name.assertInvalid();
+        name.assertErrorMessage("Name is required");
+
+        email.assertInvalid();
+        email.assertErrorMessage("Give an e-mail address or a phone number");
+
+        message.assertInvalid();
+        message.assertErrorMessage("Message is required");
+    }
+
+    @Test
+    void navigatingAwayWithUnsavedTextAsksFirst() {
+        TextFieldElement name = TextFieldElement.getByLabel(page, "Name");
+        name.setValue("Someone typing");
+
+        page.getByText("About").click();
+
+        DialogElement dialog = DialogElement.getByHeaderText(page, "Discard unsaved message?");
+        dialog.assertOpen();
+
+        ButtonElement.getByText(page, "Keep editing").click();
+        dialog.assertClosed();
+
+        assertTrue(page.url().contains("/contact"));
+        assertEquals("Someone typing", name.getValue());
+    }
+}
