+import com.vaadin.flow.component.notification.NotificationTester;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.component.textfield.TextFieldTester;
+import com.vaadin.flow.router.RouterLink;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+@SpringBootTest
+public class ContactViewTest extends SpringBrowserlessTest {
+
+    @Test
+    void headingLinkAndFormArePresent() {
+        ContactView view = navigate(ContactView.class);
+
+        H1 heading = $(H1.class).single();
+        assertEquals("Contact", heading.getText());
+
+        RouterLink about = $(RouterLink.class).withText("About").single();
+        assertEquals("about", about.getHref());
+
+        TextField name = $(TextField.class).withLabel("Name").single();
+        EmailField email = $(EmailField.class).withLabel("Email").single();
+        TextField phone = $(TextField.class).withLabel("Phone").single();
+        TextArea message = $(TextArea.class).withLabel("Message").single();
+        Button send = $(Button.class).withText("Send").single();
+
+        assertTrue(name.isEmpty());
+        assertTrue(email.isEmpty());
+        assertTrue(phone.isEmpty());
+        assertTrue(message.isEmpty());
+        assertTrue(send.isEnabled());
+    }
+
+    @Test
+    void blankFormFailsValidation() {
+        navigate(ContactView.class);
+
+        Button send = $(Button.class).withText("Send").single();
+        test(send).click();
+
+        TextField name = $(TextField.class).withLabel("Name").single();
+        EmailField email = $(EmailField.class).withLabel("Email").single();
+        TextArea message = $(TextArea.class).withLabel("Message").single();
+
+        assertTrue(name.isInvalid());
+        assertEquals("Name is required", name.getErrorMessage());
+
+        assertTrue(email.isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email.getErrorMessage());
+
+        assertTrue(message.isInvalid());
+        assertEquals("Message is required", message.getErrorMessage());
+    }
+
+    @Test
+    void invalidEmailFormatIsRejected() {
+        navigate(ContactView.class);
+
+        TextField name = $(TextField.class).withLabel("Name").single();
+        EmailField email = $(EmailField.class).withLabel("Email").single();
+        TextArea message = $(TextArea.class).withLabel("Message").single();
+        Button send = $(Button.class).withText("Send").single();
+
+        test(name).setValue("Ada");
+        test(email).setValue("not-an-email");
+        test(message).setValue("Hello there");
+
+        test(send).click();
+
+        assertTrue(email.isInvalid());
+        assertEquals("Enter a valid e-mail address", email.getErrorMessage());
+    }
+
+    @Test
+    void tooLongMessageIsRejected() {
+        navigate(ContactView.class);
+
+        TextField name = $(TextField.class).withLabel("Name").single();
+        TextField phone = $(TextField.class).withLabel("Phone").single();
+        TextArea message = $(TextArea.class).withLabel("Message").single();
+        Button send = $(Button.class).withText("Send").single();
+
+        test(name).setValue("Ada");
+        test(phone).setValue("12345");
+        test(message).setValue("x".repeat(501));
+
+        test(send).click();
+
+        assertTrue(message.isInvalid());
+        assertEquals("Message must be at most 500 characters", message.getErrorMessage());
+    }
+
+    @Test
+    void validSubmissionSendsAndClearsForm() {
+        navigate(ContactView.class);
+
+        TextField name = $(TextField.class).withLabel("Name").single();
+        EmailField email = $(EmailField.class).withLabel("Email").single();
+        TextArea message = $(TextArea.class).withLabel("Message").single();
+        Button send = $(Button.class).withText("Send").single();
+
+        test(name).setValue("Ada Lovelace");
+        test(email).setValue("ada@example.com");
+        test(message).setValue("Hello, world!");
+
+        test(send).click();
+
+        Notification notification = $(Notification.class).single();
+        assertTrue(test(notification).getText().contains("Message sent"));
+
+        assertTrue(name.isEmpty());
+        assertTrue(email.isEmpty());
+        assertTrue(message.isEmpty());
+
+        assertFalse(send.isEnabled());
+
+        Grid<ContactMessage> grid = $(Grid.class).single();
+        assertEquals("Ada Lovelace", grid.getListDataView().getItem(0).name());
+
+        test(name).setValue("A");
+        assertTrue(send.isEnabled());
+    }
+
+    @Test
+    void sendingWithEnterWorks() {
+        navigate(ContactView.class);
+
+        TextField name = $(TextField.class).withLabel("Name").single();
+        TextField phone = $(TextField.class).withLabel("Phone").single();
+        TextArea message = $(TextArea.class).withLabel("Message").single();
+
+        test(name).setValue("Grace Hopper");
+        test(phone).setValue("555-1234");
+        test(message).setValue("Testing enter to send");
+
+        fireShortcut(Key.ENTER);
+
+        Notification notification = $(Notification.class).single();
+        assertTrue(test(notification).getText().contains("Message sent"));
+    }
+
+    @Test
+    void listPersistsAcrossVisitsNewestFirst() {
+        navigate(ContactView.class);
+
+        TextField name = $(TextField.class).withLabel("Name").single();
+        TextField phone = $(TextField.class).withLabel("Phone").single();
+        TextArea message = $(TextArea.class).withLabel("Message").single();
+        Button send = $(Button.class).withText("Send").single();
+
+        int before = $(Grid.class).single().getListDataView().getItemCount();
+
+        test(name).setValue("Unique First Person");
+        test(phone).setValue("111");
+        test(message).setValue("First message");
+        test(send).click();
+
+        test(name).setValue("Unique Second Person");
+        test(phone).setValue("222");
+        test(message).setValue("Second message");
