+
+        Grid<ContactMessage> grid = $(Grid.class).single();
+        assertEquals(before + 2, grid.getListDataView().getItemCount());
+        assertEquals("Unique Second Person", grid.getListDataView().getItem(0).name());
+        assertEquals("Unique First Person", grid.getListDataView().getItem(1).name());
